// Folk songs from the user's Drive folders „ალაზანი“ (ensembles, soloists, old recordings) and „ანჩისხატი“
// (5 სიმღერები). Generated by a scratch script from the folder listing: one song per title and region (a sub-area
// such as ხევი keeps a generic title like „ნანა“ apart); a region is set only where a file name, the folder or the
// song itself names it — files with an unclear region were left out. Merged into FOLK_SONGS by songsData.ts.
import type { FolkRegionId } from './songsData';

/** One recording: Drive file id, performer (index into WHO), remark ("ხუხუნაიშვილების ვარიანტი") */
export type ArchiveRec = [id: string, who: number, note?: string];

export interface ArchiveSong {
  id: string;
  title: string;
  region: FolkRegionId;
  area?: string; // sub-area: ხევი, ხევსურეთი, თუშეთი, ლეჩხუმი…
  genre?: string;
  recs: ArchiveRec[];
}

